mapper.select:
SELECT gp.id AS product_id, gp.name AS product_name, p.id AS pid, p.name AS pname, p.workshop AS workshop, p.duration AS duration, GROUP_CONCAT(DISTINCT e.name ORDER BY e.name) AS equipment, GROUP_CONCAT(DISTINCT q.name ORDER BY q.name) AS risks, GROUP_CONCAT(DISTINCT d.name ORDER BY d.name) AS defects FROM graph_product gp JOIN product_process pp ON gp.id = pp.product_id JOIN process_node p ON pp.process_id = p.id LEFT JOIN process_equipment pe ON p.id = pe.process_id LEFT JOIN equipment e ON pe.equipment_id = e.id LEFT JOIN process_risk pr ON p.id = pr.process_id LEFT JOIN quality_risk q ON pr.risk_id = q.id LEFT JOIN risk_defect rd ON q.id = rd.risk_id LEFT JOIN defect d ON rd.defect_id = d.id WHERE gp.id IN
#{pid}
AND gp.category = 'benchmark' GROUP BY gp.id, gp.name, p.id, p.name, p.workshop, p.duration ORDER BY gp.id, p.id

WITH RECURSIVE process_chain AS ( -- 锚点：起始工序 SELECT p.id, p.name, p.workshop, p.duration, 0 AS depth FROM process_node p WHERE p.id = #{processId}
UNION ALL
-- 递归：沿 NEXT_STEP 继续往下走 SELECT pn.id, pn.name, pn.workshop, pn.duration, pc.depth + 1 FROM process_chain pc JOIN process_next_step pns ON pc.id = pns.from_id JOIN process_node pn ON pns.to_id = pn.id WHERE pc.depth < 20 -- 安全上限，防无限递归 ) SELECT pc.id AS pid, pc.name AS pname, pc.workshop AS workshop, pc.duration AS duration, pc.depth AS depth, GROUP_CONCAT(DISTINCT e.name ORDER BY e.name) AS equipment, GROUP_CONCAT(DISTINCT q.name ORDER BY q.name) AS risks, GROUP_CONCAT(DISTINCT d.name ORDER BY d.name) AS defects FROM process_chain pc LEFT JOIN process_equipment pe ON pc.id = pe.process_id LEFT JOIN equipment e ON pe.equipment_id = e.id LEFT JOIN process_risk pr ON pc.id = pr.process_id LEFT JOIN quality_risk q ON pr.risk_id = q.id LEFT JOIN risk_defect rd ON q.id = rd.risk_id LEFT JOIN defect d ON rd.defect_id = d.id GROUP BY pc.id, pc.name, pc.workshop, pc.duration, pc.depth ORDER BY pc.depth, pc.id
